const path = require('path')
const os = require('os')

/**
 * 记忆根目录。刻意放在家目录下、独立的 ~/life/，
 * 而不是 userData 里：这些文件是用户的，应当可读、可 git、可用任何编辑器改。
 * 环境变量 HUNDUN_LIFE_DIR 可覆盖（测试用）。
 */
function lifeDir() {
  return process.env.HUNDUN_LIFE_DIR || path.join(os.homedir(), 'life')
}

function memoryDir() {
  return path.join(lifeDir(), 'memory')
}

/** 允许渲染进程读写的相对路径白名单校验，防目录穿越 */
function resolveInside(relPath) {
  const root = lifeDir()
  const abs = path.resolve(root, relPath)
  if (abs !== root && !abs.startsWith(root + path.sep)) {
    throw new Error('路径越界: ' + relPath)
  }
  return abs
}

module.exports = { lifeDir, memoryDir, resolveInside }

const fs = require('fs')
const path = require('path')
const { app } = require('electron')

const DEFAULTS = {
  baseUrl: 'https://api.deepseek.com/v1',
  apiKey: '',
  model: 'deepseek-chat',
  temperature: 0.7,
  contextWindow: 32000,
  // 检查点：默认两个点。时间由用户在设置里改，不硬编码在代码里。
  checkpoints: [
    { id: 'morning', label: '早间', time: '08:30', enabled: true },
    { id: 'evening', label: '晚间', time: '21:30', enabled: true }
  ],
  quietDate: '', // 等于今天日期时，当天所有检查点静音
  windowBounds: null
}

let cache = null

function configPath() {
  return path.join(app.getPath('userData'), 'config.json')
}

function read() {
  if (cache) return cache
  try {
    const raw = fs.readFileSync(configPath(), 'utf8')
    const parsed = JSON.parse(raw)
    cache = { ...DEFAULTS, ...parsed }
    // 数组字段单独兜底，避免旧配置缺项
    if (!Array.isArray(cache.checkpoints) || cache.checkpoints.length === 0) {
      cache.checkpoints = DEFAULTS.checkpoints.map((c) => ({ ...c }))
    }
  } catch {
    cache = JSON.parse(JSON.stringify(DEFAULTS))
  }
  return cache
}

function write(patch) {
  const next = { ...read(), ...patch }
  cache = next
  const file = configPath()
  fs.mkdirSync(path.dirname(file), { recursive: true })
  fs.writeFileSync(file, JSON.stringify(next, null, 2), { mode: 0o600 })
  try {
    fs.chmodSync(file, 0o600)
  } catch {}
  return next
}

/** 给渲染进程用：不带任何敏感字段以外的裁剪，key 由用户自己填自己看 */
function publicConfig() {
  const c = read()
  return { ...c, hasApiKey: Boolean(c.apiKey && c.apiKey.trim()) }
}

function todayStr() {
  const d = new Date()
  const p = (n) => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`
}

function isQuietToday() {
  return read().quietDate === todayStr()
}

function toggleQuiet() {
  const on = !isQuietToday()
  write({ quietDate: on ? todayStr() : '' })
  return on
}

module.exports = { read, write, publicConfig, todayStr, isQuietToday, toggleQuiet, DEFAULTS }

