function endpoint(baseUrl) {
  let u = String(baseUrl || '').trim().replace(/\/+$/, '')
  if (!u) throw new Error('还没有填 API 地址')
  if (!/^https?:\/\//i.test(u)) u = 'https://' + u
  if (!/\/chat\/completions$/.test(u)) u += '/chat/completions'
  return u
}

function headers(apiKey) {
  return {
    'Content-Type': 'application/json',
    Authorization: 'Bearer ' + String(apiKey || '').trim()
  }
}

async function readError(res) {
  let text = ''
  try {
    text = await res.text()
  } catch {}
  let msg = text
  try {
    const j = JSON.parse(text)
    msg = j.error?.message || j.message || text
  } catch {}
  return '模型接口返回 ' + res.status + (msg ? '：' + String(msg).slice(0, 300) : '')
}

/** 流式对话；返回完整文本 */
async function streamChat({ baseUrl, apiKey, model, messages, temperature = 0.7 }, onDelta, signal) {
  const res = await fetch(endpoint(baseUrl), {
    method: 'POST',
    headers: headers(apiKey),
    body: JSON.stringify({ model, messages, temperature, stream: true }),
    signal
  })

  if (!res.ok) throw new Error(await readError(res))
  if (!res.body) throw new Error('模型没有返回数据流')

  const reader = res.body.getReader()
  const decoder = new TextDecoder('utf-8')
  let buf = ''
  let full = ''

  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    buf += decoder.decode(value, { stream: true })

    let nl
    while ((nl = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, nl).trim()
      buf = buf.slice(nl + 1)
      if (!line || line.startsWith(':')) continue
