```js
const life = require('./life')
const store = require('./store')
const llm = require('./llm')

const MAX_TURNS = 40
let history = []
let summary = ''

function reset() { history = []; summary = '' }
function getHistory() { return { history: history.map(m=>({role:m.role,content:m.content})), summary } }

const BLOCK_RE = /<(memory|longterm|profile)>([\s\S]*?)<\/\1>/gi

function parseBlocks(text) {
  const notes = []
  let clean = text.replace(BLOCK_RE, (_, tag, body) => {
    const lines = body.split('\n').map(s=>s.trim()).filter(Boolean)
    if (lines.length) notes.push({ target: tag.toLowerCase(), lines })
    return ''
  }).trim()
  return { clean, notes }
}

function persist(notes) {
  const by = { memory: [], longterm: [], profile: [] }
  for (const n of notes) by[n.target].push(...n.lines)
  const written = []
  if (by.memory.length) written.push(life.appendJournal(by.memory))
  if (by.longterm.length) written.push(life.appendLongterm(by.longterm))
  if (by.profile.length) written.push(life.appendProfile(by.profile))
  return written
}
