async function send(text, opts={}) {
  const cfg = store.read()
  if (!cfg.apiKey) throw new Error('还没有填 API Key，先点右上角设置')
  await maybeCompact()
  history.push({role:'user', content: text})
  const messages = [{role:'system', content: life.buildSystemPrompt({summary})}, ...history.slice(-MAX_TURNS)]
  let acc = ''
  const full = await llm.streamChat({...}, (d)=>{acc+=d; opts.onDelta(d)}, opts.signal)
  const raw = full || acc
  const { clean, notes } = parseBlocks(raw)
  const written = persist(notes)
  history.push({role:'assistant', content: clean})
  return { text: clean, raw, notes, written }
}
```

