:root {
  --bg: #fff8e8;
  --bg-deep: #fff3d6;
  --panel: #fffdf6;
  --line: #e8dcc0;
  --line-soft: #f0e6cf;
  --ink: #2a2118;
  --ink-2: #6b5d4a;
  --ink-3: #9c8d76;
  --accent: #c3272b;
  --accent-soft: #f7e2df;
  --shadow-card: 0 1px 2px rgba(42, 33, 24, 0.05), 0 6px 18px rgba(42, 33, 24, 0.04);
  --radius: 10px;
  --titlebar-h: 46px;
}

* {
  box-sizing: border-box;
}

html,
body,
#app {
  height: 100%;
  margin: 0;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: 'Noto Sans SC', 'Source Han Sans SC', 'Microsoft YaHei', system-ui, sans-serif;
  font-size: 14.5px;
  line-height: 1.72;
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  cursor: default;
  user-select: none;
}

::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}
::-webkit-scrollbar-thumb {
  background: #e2d5b8;
  border-radius: 9px;
  border: 2px solid transparent;
  background-clip: content-box;
}
::-webkit-scrollbar-thumb:hover {
  background: #cfbd98;
  background-clip: content-box;
}
::-webkit-scrollbar-track {
  background: transparent;
}

/* ---------------- 外壳 ---------------- */

.shell {
  height: 100%;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  overflow: hidden;
}

.titlebar {
  height: var(--titlebar-h);
  flex: 0 0 var(--titlebar-h);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 8px 0 16px;
  background: var(--bg-deep);
  border-bottom: 1px solid var(--line);
  -webkit-app-region: drag;
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.mark {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--accent);
  color: #fff8e8;
  font-size: 12px;
  line-height: 22px;
  text-align: center;
  font-weight: 700;
  flex: 0 0 22px;
}

.brand small {
  font-weight: 400;
  color: var(--ink-3);
  font-size: 11.5px;
  letter-spacing: 0.06em;
}

.spacer {
  flex: 1;
}

.tbtn {
  -webkit-app-region: no-drag;
  height: 28px;
  min-width: 28px;
  padding: 0 9px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent;
  color: var(--ink-2);
  font-size: 12.5px;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.14s, color 0.14s, border-color 0.14s;
}
.tbtn:hover {
  background: #f6ecd2;
  color: var(--ink);
}
.tbtn.on {
  background: var(--accent-soft);
  color: var(--accent);
  border-color: #eccfcb;
}
.tbtn.win:hover {
  background: #efdfbc;
}
.tbtn.win.close:hover {
  background: var(--accent);
  color: #fff8e8;
}

/* ---------------- 主体 ---------------- */

.body {
  flex: 1;
  display: flex;
  min-height: 0;
}

.chat-col {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: var(--bg);
}

.messages {
  flex: 1;
  overflow-y: auto;
  padding: 26px 32px 10px;
  scroll-behavior: smooth;
  user-select: text;
}

.msg {
  max-width: 660px;
  margin: 0 auto 26px;
  display: flex;
  gap: 12px;
  animation: rise 0.3s ease both;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  flex: 0 0 26px;
  margin-top: 3px;
  background: var(--accent);
  color: #fff8e8;
  font-size: 12.5px;
  line-height: 26px;
  text-align: center;
  font-weight: 700;
}

.msg.me {
  flex-direction: row-reverse;
}

.msg.me .bubble {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 12px 12px 3px 12px;
  padding: 9px 14px;
  box-shadow: var(--shadow-card);
  color: var(--ink);
}

.msg .content {
  min-width: 0;
  flex: 1;
}

.msg.me .content {
  display: flex;
  justify-content: flex-end;
}

.msg.me .bubble {
  max-width: 88%;
}

.msg .content p {
  margin: 0 0 10px;
}
.msg .content p:last-child {
  margin-bottom: 0;
}
.msg .content h1,
.msg .content h2,
.msg .content h3,
.msg .content h4 {
  font-size: 15px;
  margin: 16px 0 8px;
  letter-spacing: 0.01em;
}
.msg .content ul {
  margin: 8px 0;
  padding-left: 20px;
}
.msg .content li {
  margin: 3px 0;
}
.msg .content code {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-size: 12.5px;
  background: #f4ead2;
  border-radius: 4px;
  padding: 1px 5px;
  color: #7a4a22;
}
.msg .content pre {
  background: #2a2118;
  color: #f3e9d6;
  border-radius: 8px;
  padding: 12px 14px;
  overflow-x: auto;
  font-size: 12.5px;
  line-height: 1.6;
}
.msg .content pre code {
  background: none;
  color: inherit;
  padding: 0;
}

.caret {
  display: inline-block;
  width: 7px;
  height: 15px;
  background: var(--accent);
  vertical-align: -2px;
  margin-left: 2px;
  animation: blink 1.05s steps(2, start) infinite;
}
@keyframes blink {
  to {
    visibility: hidden;
  }
}

.divider {
  max-width: 660px;
  margin: 6px auto 24px;
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--ink-3);
  font-size: 11.5px;
  letter-spacing: 0.1em;
}
.divider::before,
.divider::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--line-soft);
}

.notice {
  max-width: 660px;
  margin: 0 auto 22px;
  padding: 9px 13px;
  border-radius: 8px;
  background: #fdf1e4;
  border: 1px solid #f2ddc2;
  color: #8a5a2b;
  font-size: 12.5px;
}
.notice.bad {
  background: #fbebe9;
  border-color: #f0ccc7;
  color: #a13a2f;
}

.empty {
  max-width: 520px;
  margin: 12vh auto 0;
  text-align: center;
  color: var(--ink-3);
  line-height: 2;
}
.empty .big {
  font-size: 16px;
  color: var(--ink-2);
  margin-bottom: 6px;
}

/* ---------------- 输入 ---------------- */

.composer {
  flex: 0 0 auto;
  padding: 10px 32px 20px;
}

.composer-inner {
  max-width: 660px;
  margin: 0 auto;
  display: flex;
  align-items: flex-end;
  gap: 10px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 8px 8px 8px 14px;
  box-shadow: var(--shadow-card);
  transition: border-color 0.16s, box-shadow 0.16s;
}
.composer-inner:focus-within {
  border-color: #d9b7a4;
  box-shadow: 0 0 0 3px rgba(195, 39, 43, 0.07);
}

textarea {
  flex: 1;
  border: 0;
  outline: 0;
  resize: none;
  background: transparent;
  font-family: inherit;
  font-size: 14.5px;
  line-height: 1.7;
  color: var(--ink);
  max-height: 168px;
  padding: 5px 0;
  user-select: text;
}
textarea::placeholder {
  color: #b7a88e;
}

.send {
  flex: 0 0 auto;
  height: 34px;
  padding: 0 16px;
  border: 0;
  border-radius: 9px;
  background: var(--accent);
  color: #fff8e8;
  font-family: inherit;
  font-size: 13.5px;
  cursor: pointer;
  transition: opacity 0.14s, transform 0.1s;
}
.send:hover {
  opacity: 0.9;
}
.send:active {
  transform: translateY(1px);
}
.send:disabled {
  background: #e3d4b6;
  color: #a89madeup;
  cursor: default;
  opacity: 1;
}

.hint {
  max-width: 660px;
  margin: 7px auto 0;
  font-size: 11px;
  color: var(--ink-3);
  display: flex;
  justify-content: space-between;
}

/* ---------------- 记忆面板 ---------------- */

.memory {
  flex: 0 0 342px;
  width: 342px;
  border-left: 1px solid var(--line);
  background: var(--bg-deep);
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.memory-head {
  flex: 0 0 auto;
  padding: 14px 16px 10px;
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--line-soft);
}

.memory-head h2 {
  margin: 0;
  font-size: 12px;
  letter-spacing: 0.14em;
  color: var(--ink-2);
  font-weight: 600;
}

.mini {
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink-2);
  border-radius: 6px;
  height: 24px;
  padding: 0 8px;
  font-size: 11.5px;
  font-family: inherit;
  cursor: pointer;
}
.mini:hover {
  border-color: #d6c39c;
  color: var(--ink);
}

.filelist {
  flex: 0 0 auto;
  max-height: 190px;
  overflow-y: auto;
  padding: 8px;
  border-bottom: 1px solid var(--line-soft);
}

.file {
  padding: 5px 9px;
  border-radius: 6px;
  font-size: 12.5px;
  color: var(--ink-2);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  gap: 8px;
}
.file:hover {
  background: #f6ecd2;
}
.file.active {
  background: #f3e3c4;
  color: var(--ink);
  font-weight: 600;
}
.file .meta {
  color: var(--ink-3);
  font-size: 10.5px;
  flex: 0 0 auto;
}

.editor-wrap {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 10px 12px 12px;
}

.editor-wrap .path {
  font-size: 11px;
  color: var(--ink-3);
  letter-spacing: 0.04em;
  margin-bottom: 7px;
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.editor-wrap textarea {
  flex: 1;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 12.5px;
  line-height: 1.75;
  max-height: none;
  overflow-y: auto;
}

.editor-foot {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  font-size: 11px;
  color: var(--ink-3);
}

/* ---------------- 设置弹窗 ---------------- */

.mask {
  position: fixed;
  inset: 0;
  background: rgba(42, 33, 24, 0.28);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 20;
  -webkit-app-region: no-drag;
}

.modal {
  width: 540px;
  max-height: 86vh;
  overflow-y: auto;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: 0 18px 50px rgba(42, 33, 24, 0.18);
  padding: 22px 24px 20px;
}

.modal h2 {
  margin: 0 0 4px;
  font-size: 16px;
}
.modal .sub {
  margin: 0 0 18px;
  font-size: 12px;
  color: var(--ink-3);
}

.field {
  margin-bottom: 14px;
}
.field label {
  display: block;
  font-size: 12px;
  color: var(--ink-2);
  margin-bottom: 5px;
  letter-spacing: 0.03em;
}
.field input {
  width: 100%;
  height: 34px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fffefa;
  padding: 0 11px;
  font-family: inherit;
  font-size: 13px;
  color: var(--ink);
  outline: 0;
  user-select: text;
}
.field input:focus {
  border-color: #d9b7a4;
  box-shadow: 0 0 0 3px rgba(195, 39, 43, 0.06);
}
.field .tip {
  font-size: 11px;
  color: var(--ink-3);
  margin-top: 5px;
}

.row2 {
  display: flex;
  gap: 12px;
}
.row2 > * {
  flex: 1;
}

.cp-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 9px;
}
.cp-row span {
  width: 54px;
  font-size: 12.5px;
  color: var(--ink-2);
}
.cp-row input[type='time'] {
  width: 108px;
  height: 32px;
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 0 8px;
  font-family: inherit;
  font-size: 13px;
  background: #fffefa;
  color: var(--ink);
}
.cp-row input[type='checkbox'] {
  width: 15px;
  height: 15px;
  accent-color: var(--accent);
}

.modal-foot {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--line-soft);
}

.btn {
  height: 33px;
  padding: 0 15px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--ink);
  font-family: inherit;
  font-size: 13px;
  cursor: pointer;
}
.btn:hover {
  border-color: #d6c39c;
}
.btn.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff8e8;
}
.btn.primary:hover {
  opacity: 0.92;
}
.btn:disabled {
  opacity: 0.55;
  cursor: default;
}

.status {
  font-size: 12px;
  color: var(--ink-2);
}
.status.ok {
  color: #3f7d4e;
}
.status.bad {
  color: #a13a2f;
}
