    if (res?.error) { notice = res.error; noticeBad = true; messages.value[liveIdx.value]?. ... }
    else if (res?.text) finalize(res.text)
  } finally {
    streaming.value = false
    if (liveIdx.value >= 0) finalize(messages.value[liveIdx.value].content || '（没说话）')
  }
}
