  } finally {
    streaming.value = false
    await refreshTree()
  }
}

/* ---------- 事件 ---------- */

let offs = []

onMounted(async () => {
  cfg.value = await window.hundun.cfg.get()
  quiet.value = await window.hundun.quiet.get()
