const https = require('https')
const http = require('http')
const { URL } = require('url')

/**
 * OpenAI 兼容协议的极简客户端。
 *
 * 刻意不用 fetch：本机环境的 Node 内建 fetch 依赖 undici 的 WASM，
 * 在虚拟内存受限时会直接 OOM 崩掉（实测）。用 node:https 手写 SSE 解析，
 * 零依赖、无 WASM、行为可控。
 */

function endpoint(baseUrl) {
  let u = String(baseUrl || '').trim().replace(/\/+$/, '')
  if (!u) throw new Error('还没有填 API 地址')
  if (!/^https?:\/\//i.test(u)) u = 'https://' + u
  if (!/\/chat\/completions$/.test(u)) u += '/chat/completions'
  return u
}

function post(urlStr, payload, apiKey, onChunk) {
  return new Promise((resolve, reject) => {
    let url
    try {
      url = new URL(urlStr)
    } catch {
      return reject(new Error('API 地址格式不对：' + urlStr))
    }
    const mod = url.protocol === 'http:' ? http : https
    const body = Buffer.from(JSON.stringify(payload), 'utf8')

    const req = mod.request(
      {
        protocol: url.protocol,
        hostname: url.hostname,
        port: url.port || (url.protocol === 'http:' ? 80 : 443),
        path: url.pathname + url.search,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': body.length,
          Authorization: 'Bearer ' + String(apiKey || '').trim(),
          Accept: payload.stream ? 'text/event-stream' : 'application/json'
        },
        timeout: 180000
      },
      (res) => {
        if (res.statusCode !== 200) {
          let err = ''
          res.setEncoding('utf8')
          res.on('data', (d) => (err += d))
          res.on('end', () => {
            let msg = err
            try {
              const j = JSON.parse(err)
              msg = j.error?.message || j.message || err
            } catch {}
            reject(new Error('模型接口返回 ' + res.statusCode + (msg ? '：' + String(msg).slice(0, 300) : '')))
          })
          return
        }
        res.setEncoding('utf8')
        resolve({ res, stream: Boolean(payload.stream) })
      }
    )

    req.on('timeout', () => {
      req.destroy(new Error('请求超时（180 秒）'))
    })
    req.on('error', (e) => reject(new Error('连不上模型接口：' + e.message)))
    req.write(body)
    req.end()

    if (onChunk) req._onChunk = onChunk
  })
}

