{"content": "/**
 * 端到端测试：真的跑一轮对话。
 *
 * 做法：把 electron 模块替换成一个用 node:http 实现的 net 桩，
 * 这样 conversation.send 的完整链路（拼提示 → 流式收字 → 抠记忆块 → 落盘）
 * 都能在纯 Node 里跑，不需要 Chromium。
 *
 * 依赖：先起假模型服务
 *   python3 scripts/mock-llm.py 8787
 *   node scripts/test-e2e.mjs
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import esbuild from 'esbuild'
import { createRequire } from 'node:module'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const require = createRequire(import.meta.url)
const TMP = path.join(ROOT, '.dev/e2e')

let pass = 0
let fail = 0
const ok = (c, n, e = '') => {
  if (c) {
    pass++
    console.log('  ✓ ' + n)
  } else {
    fail++
    console.log('  ✗ ' + n + (e ? '  → ' + e : ''))
  }
}

/* electron 桩：只实现 llm.js 用到的 net.request 和 store.js 用到的 app.getPath */
const stub = path.join(ROOT, '.dev/electron-stub.cjs')
fs.mkdirSync(path.dirname(stub), { recursive: true })
fs.writeFileSync(
  stub,
  `
const http = require('http')
const https = require('https')
const { EventEmitter } = require('events')

const app = { getPath: () => process.env.HUNDUN_CONFIG_DIR }

function request(options) {
  const emitter = new EventEmitter()
  const u = new URL(options.url)
  const mod = u.protocol === 'https:' ? https : http
  const req = mod.request(
    { hostname: u.hostname, port: u.port, path: u.pathname + u.search, method: options.method || 'GET' },
    (res) => emitter.emit('response', res)
  )
  req.on('error', (e) => emitter.emit('error', e))
  return {
    setHeader: (k, v) => req.setHeader(k, v),
    write: (d) => req.write(d),
    end: () => req.end(),
    abort: () => req.destroy(),
    on: (ev, cb) => {
      emitter.on(ev, cb)
      return this
    }
  }
}

module.exports = { app, net: { request } }
`
)

/* 打包主进程模块，把 electron 指向桩 */
const bundle = path.join(ROOT, '.dev/e2e-main.cjs')
await esbuild.build({
  entryPoints: [path.join(ROOT, '.dev/e2e-entry.js')],
  bundle: true,
  platform: 'node',
  format: 'cjs',
  target: 'node18',
  outfile: bundle,
  logLevel: 'silent',
  plugins: [
    {
      name: 'stub-electron',
      setup(b) {
        b.onResolve({ filter: /^electron$/ }, () => ({ path: stub }))
      }
    }
  ]
