/**
 * 检索索引的全部 SQL 语句。
 * 单独成文件是为了能用系统 sqlite3（测试里用 Python 的 sqlite3）做语义验证。
 */
module.exports = {
  schema: [
    `CREATE TABLE IF NOT EXISTS notes (
 id INTEGER PRIMARY KEY,
       file TEXT NOT NULL,
       day TEXT,
       line INTEGER,
       text TEXT NOT NULL
     )`,
    `CREATE INDEX IF NOT EXISTS idx_notes_day ON notes(day)`,
    `CREATE INDEX IF NOT EXISTS idx_notes_file ON notes(file)`,
    `CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT)`
  ],
  clear: 'DELETE FROM notes',
  insert: 'INSERT INTO notes (file, day, line, text) VALUES (?, ?, ?, ?)',
  count: 'SELECT COUNT(*) AS n FROM notes',
  byTerm: "SELECT file, day, line, text FROM notes WHERE instr(lower(text), lower(?)) > 0 LIMIT ?",
  setMeta: 'INSERT OR REPLACE INTO meta (key, value) VALUES (?, ?)',
  getMeta: 'SELECT value FROM meta WHERE key = ?'
}
```

`instr(lower(text), lower(?))` — portable LIKE without wildcards escaping issues. instr exists in SQLite. Good — avoids % escaping problems with user input containing % or _.

search.js:

```js
const fs = require('fs')
const path = require('path')
const life = require('./life')
const SQLS = require('./search-sql')

let readyPromise = null
let backend = null

function dbPath() { return path.join(life.lifeDir(), '.index', 'memory.sqlite') }

function init() {
  if (!readyPromise) readyPromise = doInit()
  return readyPromise
}

async function doInit() {
  try {
    const vendorDir = path.join(__dirname, 'vendor')
    const initSqlJs = require(path.join(vendorDir, 'sql-wasm.js'))
    const wasmBinary = fs.readFileSync(path.join(vendorDir, 'sql-wasm.wasm'))
    const SQL = await initSqlJs({ wasmBinary })
    let db
    const p = dbPath()
    if (fs.existsSync(p)) {
      db = new SQL.Database(fs.readFileSync(p))
    } else {
      db = new SQL.Database()
      for (const s of SQLS.schema) db.run(s)
    }
    backend = { kind: 'sqlite', db, persist() {
      fs.mkdirSync(path.dirname(p), { recursive: true })
      fs.writeFileSync(p, Buffer.from(db.export()))
    }}
  } catch (e) {
    backend = {
      kind: 'memory',
      rows: [],
      persist() {}
    }
    backend.error = e.message
  }
  return backend
}
```

Hmm — in dev (`electron .` from project root, out/main/index.js), __dirname = out/main → vendor at out/main/vendor. Good.

