```js
function collectRows() {
  const root = life.lifeDir()
  const rows = []
  const walk = (dir, rel) => {
    for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
      const r = rel ? rel + '/' + ent.name : ent.name
      if (ent.isDirectory()) {
        if (ent.name === '.index') continue
        walk(path.join(dir, ent.name), r)
      } else if (ent.name.endsWith('.md')) {
        const txt = fs.readFileSync(path.join(dir, ent.name), 'utf8')
        const day = (ent.name.match(/(\d{4}-\d{2}-\d{2})/) || [])[1] || null
        txt.split('\n').forEach((line, i) => {
          const t = line.trim()
          if (t.length >= 4 && !t.startsWith('#')) rows.push({ file: r, day, line: i + 1, text: t })
        })
      }
    }
  }
  walk(root, '')
  return rows
}
```

rebuild():
```js
async function rebuild() {
  const b = await init()
  const rows = collectRows()
  if (b.kind === 'sqlite') {
    b.db.run(SQLS.clear)
    for (const r of rows) b.db.run(SQLS.insert, [r.file, r.day, r.line, r.text])
    b.db.run(SQLS.setMeta, ['built_at', new Date().toISOString()])
    b.persist()
  } else {
    b.rows = rows
  }
  return rows.length
}
```

