      (res) => {
        res.resume()
        resolve(true)
      }
    )
    req.on('error', () => resolve(false))
    req.setHeader('Content-Type', 'application/json')
    req.end(JSON.stringify({ messages: [{ role: 'user', content: 'ping' }] }))
  })
}
if (!up) {
  console.error('假模型服务没起来，端口 ' + PORT)
  mock.kill()
  process.exit(1)
}
